      "card_ids": ["C15"],
      "claim": "Praziquantel reached brain concentrations of 5.7 µg/g within 5 minutes after intravenous dosing in rats, showing rapid and substantial BBB permeation.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Granisetron microdialysis in rats showed an increasing unbound brain/blood ratio after intravenous dosing, confirming active BBB penetration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Phenserine in rats reached brain levels approximately 10-fold higher than plasma, demonstrating preferential CNS distribution despite a basic amine-containing structure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "A related rigid heterocyclic compound in rats had a brain:plasma penetration ratio of 3.94 and was classified as highly CNS penetrant.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Pass: multiple high-transfer direct CNS penetration measurements in rats and mice support meaningful brain access, and the physicochemical profile is favorable for passive BBB permeability.",
